def signal(obs):
    # simple imbalance signal on A and B
    out={}
    for asset in ['A','B','C','IDX']:
        imb = obs.hist(asset,'imbalance',50)
        if not np.isfinite(imb[-1]):
            continue
        # 50 period mean
        m = np.nanmean(imb)
        s = np.nanstd(imb)
        if s<1e-9 or not np.isfinite(s):
            continue
        z = (imb[-1]-m)/s
        # imbalance predicts future positive return, so long if z positive
        # threshold 0.5
        if abs(z) < 0.8:
            out[asset]=0.0
        else:
            pos = np.clip(z*0.5, -1,1)
            out[asset]=float(pos)
    # Don't trade X venues, set 0
    out['A.X']=0.0; out['B.X']=0.0; out['C.X']=0.0
    return out

