def signal(obs):
    st = obs.state
    if 'ew' not in st:
        st['ew'] = {}
    ew = st['ew']
    out = {}
    def lm(a, f):
        try:
            v = obs.last(a, f)
        except:
            return None
        try:
            fv = float(v)
        except:
            try:
                fv = float(v[-1])
            except:
                return None
        if fv != fv:
            return None
        return fv
    pairs = [('A', 'A.X'), ('C', 'C.X')]
    cfg = {'A': (20.0, 10.0), 'C': (30.0, 12.0)}
    for a, b in pairs:
        ma = lm(a, 'mid')
        mb = lm(b, 'mid')
        if ma is None or mb is None:
            continue
        sa = lm(a, 'spread')
        sb = lm(b, 'spread')
        if sa is None or sa != sa:
            sa = 10.0
        if sb is None or sb != sb:
            sb = 10.0
        gap = ma - mb
        fee = mb * 0.0003
        if fee != fee:
            fee = 3.0
        dead = cfg[a][1]
        scale = cfg[a][0]
        raw = 0.0
        if gap > dead:
            mag = (gap - dead) / scale
            if mag > 1.0:
                mag = 1.0
            raw = mag
        elif gap < -dead:
            mag = (-gap - dead) / scale
            if mag > 1.0:
                mag = 1.0
            raw = -mag
        else:
            raw = 0.0
        key = a + b
        prev = ew.get(key, 0.0)
        if prev != prev:
            prev = 0.0
        sm = 0.3 * raw + 0.7 * prev
        if abs(sm) < 0.1:
            sm = 0.0
        ew[key] = sm
        ta = -sm
        tb = sm * 0.9
        if ta > 1.0:
            ta = 1.0
        if ta < -1.0:
            ta = -1.0
        if tb > 1.0:
            tb = 1.0
        if tb < -1.0:
            tb = -1.0
        out[a] = ta
        out[b] = tb
    try:
        imbA = lm('A', 'imbalance')
        if imbA is None or imbA != imbA:
            imbA = 0.0
        pa = out.get('A', 0.0)
        if abs(pa) < 0.15:
            tilt = imbA * 0.4
            if tilt > 0.5:
                tilt = 0.5
            if tilt < -0.5:
                tilt = -0.5
            prevt = ew.get('tiltA', 0.0)
            if prevt != prevt:
                prevt = 0.0
            smt = 0.2 * tilt + 0.8 * prevt
            ew['tiltA'] = smt
            if abs(smt) < 0.12:
                smt = 0.0
            out['A'] = smt
            if 'A.X' in out and abs(out['A.X']) < 0.15:
                out['A.X'] = 0.0
    except:
        pass
    for a in ['B', 'B.X', 'IDX', 'C']:
        if a not in out:
            out[a] = 0.0
    return out

