# lead-lag: does IDX lead components or vice versa? and cross-venue lead lag
def ac(a,b,lag):
  # corr of a[t] with b[t+lag]? test
  n=len(a)
  if lag>=0:
    x=a[:n-lag]; y=b[lag:]
  else:
    x=a[-lag:]; y=b[:n+lag]
  m=np.isfinite(x)&np.isfinite(y)
  x=x[m]; y=y[m]
  return float(np.corrcoef(x,y)[0,1])
