def signal(obs):
    s=obs.state
    if 'p' not in s: s['p']=0.0
    mC=obs.hist('C','mid',60)
    if mC is None or len(mC)<55:
        return {}
    last=mC[-1]
    prev=mC[-51] if len(mC)>=51 else float('nan')
    if not np.isfinite(last) or not np.isfinite(prev):
        return {}
    ret = last - prev
    thr=12
    pos=s['p']
    if ret < -thr:
        pos=-1.0
    elif ret > thr:
        pos=0.0
        if ret>25:
            pos=0.5
    else:
        if pos<0 and ret>-5:
            pos=0.0
    s['p']=pos
    return {'C': float(pos), 'C.X':0.0, 'A':0.0,'B':0.0,'IDX':0.0}

