    while j>=0 and not np.isfinite(mA[j]): j-=1
    if j<0: return {}
    ret=mA[idx]-mA[j]
    thr=6
    pos=s['pA']
    if ret>thr: pos=1
    elif ret<-thr: pos=-1
    else:
        if abs(ret)<2: pos=0
    s['pA']=pos
    return {'A':float(pos)}

def signal(obs):
    s=obs.state
    if 'pID' not in s: s['pID']=0
    midIDX=obs.hist('IDX','mid',70)
    midA=obs.hist('A','mid',70)
    midB=obs.hist('B','mid',70)
    midC=obs.hist('C','mid',70)
    if midIDX is None or len(midIDX)<30: return {}
    # compute spread
    def last_valid(a):
        for i in range(len(a)-1,-1,-1):
            if np.isfinite(a[i]): return a[i]
        return float('nan')
    a=last_valid(midA); b=last_valid(midB); c=last_valid(midC); idx=last_valid(midIDX)
    if not (np.isfinite(a) and np.isfinite(b) and np.isfinite(c) and np.isfinite(idx)): return {}
    syn=0.3333*a+0.6667*b+0.1667*c
    spread=idx-syn
    pos=s['pID']
    if spread>6: pos=-1
    elif spread<-6: pos=1
    else:
        if abs(spread)<2: pos=0
    s['pID']=pos
    return {'IDX':float(pos)}

