            past = m[-31]
        if cur!=cur or past!=past:
            continue
        r = cur-past
        # deadzone ~ 3 cents? scale to target
        # normalize: target = clip(r / 20)
        t = s*r/25.0
        if t>1: t=1
        if t<-1: t=-1
        # deadzone small moves
        if abs(r)<4:
            t=0.0
        out[a]=float(t)
    return out

