def signal(obs):
    s = obs.state
    if 'pos' not in s:
        s['pos'] = 0
        s['hold'] = 0
    wA = 0.3333
    wB = 0.6667
    wC = 0.1667
    thr_enter = 16.0
    thr_exit = 2.0
    min_hold = 30
    try:
        A = obs.hist('A','mid', 30)
        B = obs.hist('B','mid', 30)
        C = obs.hist('C','mid', 30)
        IDX = obs.hist('IDX','mid', 30)
        if A is None or B is None or C is None or IDX is None:
            return {}
        def last_valid(arr):
            for i in range(len(arr)-1, -1, -1):
                v = arr[i]
                if np.isfinite(v):
                    return float(v)
            return float('nan')
        a = last_valid(A)
        b = last_valid(B)
        c = last_valid(C)
        idx = last_valid(IDX)
        if not (np.isfinite(a) and np.isfinite(b) and np.isfinite(c) and np.isfinite(idx)):
            return {}
        basket = wA*a + wB*b + wC*c
        spread = idx - basket
        if not np.isfinite(spread):
            return {}
        pos = int(s['pos'])
        hold = int(s['hold'])
        hold += 1
        if pos == 0:
            if spread > thr_enter:
                pos = -1
                hold = 0
            elif spread < -thr_enter:
                pos = 1
                hold = 0
        elif pos == -1:
            if hold >= min_hold and spread < thr_exit:
