    st = obs.state
    assets = obs.assets
    def last_mid(a):
        try:
            v = obs.last(a, 'mid')
        except Exception:
            v = float('nan')
        return v
    # need histories for dev z-score; use hist
    try:
        n = 400
        mA = obs.hist('A','mid',n)
        mB = obs.hist('B','mid',n)
        mC = obs.hist('C','mid',n)
        mI = obs.hist('IDX','mid',n)
        # compute dev series where finite
        import math as _m
        dev = [float('nan')]*n
        for i in range(n):
            a=mA[i]; b=mB[i]; c=mC[i]; x=mI[i]
            # NaN check: NaN != NaN
            if a==a and b==b and c==c and x==x:
                dev[i]=x-(0.3333*a+0.6667*b+0.1667*c)
        # rolling mean/std over finite
        vals=[d for d in dev if d==d]
        if len(vals)<100:
            return {'IDX': 0.0}
        m=sum(vals)/len(vals)
        v=sum((d-m)*(d-m) for d in vals)/len(vals)
        s=_m.sqrt(v+1e-9)
        if s<1e-6:
            return {'IDX': 0.0}
        cur=dev[-1]
        if not cur==cur:
            return {'IDX': 0.0}
        z=(cur-m)/s
        # deadzone + clip, scale
        # target opposes dev
        t=-z*0.5
        if t>1: t=1
        if t<-1: t=-1
        # deadzone small
        if abs(z)<0.25:
            t=0.0
        return {'IDX': float(t)}
    except Exception:
        return {'IDX': 0.0}

