def signal(obs):
    # current live: IDX fade thr 18
    s = obs.state
    if 'pos' not in s:
        s['pos'] = 0
        s['hold'] = 0
    wA = 0.3333; wB = 0.6667; wC = 0.1667
    thr_enter = 18.0
    thr_exit = 3.0
    min_hold = 35
    try:
        A = obs.hist('A','mid', 30)
        B = obs.hist('B','mid', 30)
        C = obs.hist('C','mid', 30)
        IDX = obs.hist('IDX','mid', 30)
        def last_valid(arr):
            for i in range(len(arr)-1, -1, -1):
                v = arr[i]
                if np.isfinite(v):
                    return float(v)
            return float('nan')
        a = last_valid(A); b = last_valid(B); c = last_valid(C); idx = last_valid(IDX)
        if not (np.isfinite(a) and np.isfinite(b) and np.isfinite(c) and np.isfinite(idx)):
            return {}
        basket = wA*a + wB*b + wC*c
        spread = idx - basket
        pos = int(s['pos']); hold = int(s['hold']); hold+=1
        if pos==0:
            if spread > thr_enter: pos=-1; hold=0
            elif spread < -thr_enter: pos=1; hold=0
        elif pos==-1:
            if hold>=min_hold and spread < thr_exit: pos=0; hold=0
            elif hold>=min_hold and spread < -thr_enter: pos=1; hold=0
        elif pos==1:
            if hold>=min_hold and spread > -thr_exit: pos=0; hold=0
            elif hold>=min_hold and spread > thr_enter: pos=-1; hold=0
        s['pos']=pos; s['hold']=hold
        out={}
        out['IDX']=float(pos)
        out['A']=0.0; out['B']=0.0; out['C']=0.0; out['A.X']=0.0; out['B.X']=0.0; out['C.X']=0.0
        return out
    except:
        return {}

