        if abs(spread) < 5:
            sig2 = 0.0
        sig = sig2
        s['pos_sig']=sig
        out={}
        out['IDX'] = float(-sig)  # opposite spread? Wait sig is -spread/30, so -sig = spread/30? Let's be consistent:
        # If spread >0 IDX rich => want short IDX => IDX target negative. So if spread>0, sig2 negative, IDX = sig2 (negative) is correct. So set IDX = sig2
        out['IDX'] = float(sig2)
        out['A'] = float(-sig2 * wA * 1.0)  # long basket when short IDX
        out['B'] = float(-sig2 * wB * 1.0)
        out['C'] = float(-sig2 * wC * 1.0)
        # we want opposite direction to IDX: if IDX short (negative), basket long (positive) => basket = -IDX * w
        # Since IDX = sig2 (negative when spread>0), basket = -sig2 * w => positive
        out['A.X']=0.0; out['B.X']=0.0; out['C.X']=0.0
        return out
