    h_vals = [30,50]
    stats = {}
    for h in h_vals:
        diffs = []
        for t in range(h, len(combo)):
            if np.isfinite(combo[t]) and np.isfinite(combo[t-h]):
                diffs.append(combo[t]-combo[t-h])
        diffs = np.array(diffs)
        # percentiles
        diffs_sorted = np.sort(diffs)
        n = len(diffs_sorted)
        def perc(p):
            idx = int(p/100*n)
            idx = max(0, min(n-1, idx))
            return float(diffs_sorted[idx])
        stats[h] = {
            'mean': float(np.mean(diffs)),
            'std': float(np.std(diffs)),
            'p5': perc(5),
            'p25': perc(25),
            'p50': perc(50),
            'p75': perc(75),
            'p95': perc(95),
            'abs_mean': float(np.mean(np.abs(diffs))),
            'count': int(n)
        }
    result[asset]=stats
