        out['A.X'] = 0.0
        out['B.X'] = 0.0
        out['C.X'] = 0.0
        h = 50
        for base in ['A','B','C']:
            scale, thr = configs[base]
            m = obs.hist(base, 'mid', h+1)
            mx = obs.hist(base+'.X', 'mid', h+1)
            cur = float('nan')
            past = float('nan')
            if m is not None and mx is not None:
                cv = float('nan')
                cx = float('nan')
                for i in range(len(m)-1, -1, -1):
                    v = m[i]
                    if np.isfinite(v):
                        cv = float(v)
                        break
                for i in range(len(mx)-1, -1, -1):
                    v = mx[i]
                    if np.isfinite(v):
                        cx = float(v)
                        break
                if np.isfinite(cv) and np.isfinite(cx):
                    cur = (cv + cx) * 0.5
                elif np.isfinite(cv):
                    cur = cv
                elif np.isfinite(cx):
                    cur = cx
                pv = float('nan')
                px = float('nan')
                if len(m) > 0 and np.isfinite(m[0]):
                    pv = float(m[0])
                else:
                    if m is not None:
                        for v in m:
                            if np.isfinite(v):
                                pv = float(v)
                                break
                if len(mx) > 0 and np.isfinite(mx[0]):
                    px = float(mx[0])
                else:
                    if mx is not None:
                        for v in mx:
                            if np.isfinite(v):
                                px = float(v)
                                break
                if np.isfinite(pv) and np.isfinite(px):
                    past = (pv + px) * 0.5
                elif np.isfinite(pv):
                    past = pv
                elif np.isfinite(px):
                    past = px
            else:
                if m is not None:
                    for i in range(len(m)-1, -1, -1):
                        if np.isfinite(m[i]):
                            cur = float(m[i]); break
                    if np.isfinite(m[0]):
                        past = float(m[0])
            if not (np.isfinite(cur) and np.isfinite(past)):
                if base in s:
                    out[base] = float(s[base])
                else:
                    out[base] = 0.0
                continue
            ret = cur - past
            if abs(ret) < thr:
                pos = 0.0
            else:
                pos = float(np.clip(ret / scale, -1.0, 1.0))
            prev = float(s.get(base, pos))
            if pos * prev > 0:
                pos = 0.7 * pos + 0.3 * prev
                pos = float(np.clip(pos, -1, 1))
            s[base] = pos
            out[base] = pos
        return out
    except:
        return {}

