def signal(obs):
    s=obs.state
    try:
        # tune horizons per asset based on max IC blended
        configs={
            'A': (30, 30, 16.0, 6.0),
            'B': (50, 50, 8.0, 3.0),
            'C': (30, 30, 30.0, 8.0),
        }
        out={'IDX':0.0,'A.X':0.0,'B.X':0.0,'C.X':0.0}
        for base in ['A','B','C']:
            hist_h, eff_h, scale, thr = configs[base]
            # hist_h is lookback, use blended mid
            m=obs.hist(base,'mid',hist_h+1)
            mx=obs.hist(base+'.X','mid',hist_h+1)
            cur=past=float('nan')
            if m is not None and mx is not None:
                # cur = last finite
                cv=float('nan'); cx=float('nan')
                for i in range(len(m)-1,-1,-1):
                    if np.isfinite(m[i]):
                        cv=float(m[i]); break
                for i in range(len(mx)-1,-1,-1):
                    if np.isfinite(mx[i]):
                        cx=float(mx[i]); break
                if np.isfinite(cv) and np.isfinite(cx):
                    cur=(cv+cx)*0.5
                elif np.isfinite(cv):
                    cur=cv
                elif np.isfinite(cx):
                    cur=cx
                # past = first element if finite else first finite
                pv=float('nan'); px=float('nan')
                if len(m)>0 and np.isfinite(m[0]):
                    pv=float(m[0])
                else:
                    for v in m:
                        if np.isfinite(v):
                            pv=float(v); break
                if len(mx)>0 and np.isfinite(mx[0]):
                    px=float(mx[0])
                else:
                    for v in mx:
                        if np.isfinite(v):
                            px=float(v); break
                if np.isfinite(pv) and np.isfinite(px):
                    past=(pv+px)*0.5
                elif np.isfinite(pv):
                    past=pv
                elif np.isfinite(px):
                    past=px
            if not (np.isfinite(cur) and np.isfinite(past)):
                out[base]=float(s.get(base,0.0))
                continue
            ret=cur-past
            if abs(ret) < thr:
                pos=0.0
            else:
                pos=float(np.clip(ret/scale, -1, 1))
            prev=float(s.get(base, pos))
            if pos*prev>0:
                pos=0.7*pos+0.3*prev
                pos=float(np.clip(pos,-1,1))
            s[base]=pos
            out[base]=pos
        return out
    except:
        return {}

def emulate(hA,hB,hC, scA,thrA, scB,thrB, scC,thrC):
    mids={}
    spreads={}
    for base in ['A','B','C']:
        m=H[base]['mid']
        mx=H[base+'.X']['mid']
        blended=np.where(np.isfinite(m) & np.isfinite(mx),(m+mx)/2, np.where(np.isfinite(m),m,mx))
        mids[base]=blended
        # execution mid and spread use primary venue only (0 bps)
        # we need primary mid for pnl? blended pnl is approx mid of primary; use primary mid where available else blended
        # for simplicity use blended for pnl as well (close)
        spreads[base]=H[base]['spread']  # primary spread per step
        # also need primary mid for pnl execution? Use blended
    n=len(mids['A'])
    max_h=max(hA,hB,hC)
    prev_pos={'A':0.0,'B':0.0,'C':0.0}
    # position lots actual (follows execution constraint)
    pos_lots={'A':0.0,'B':0.0,'C':0.0}
    # target lots
    target_lots={'A':0.0,'B':0.0,'C':0.0}
    gross=0.0
    cost=0.0
    # for IC
    targets_list={'A':[],'B':[],'C':[]}
    fwd_list={'A':[],'B':[],'C':[]}
    # iterate per step
    # signal updates every 10 steps
    # we will loop t step by step for pnl and execution
    # first init signal at max_h aligned to 10
    next_signal = max_h
    # adjust to multiple of 10
    while next_signal % 10 != 0:
        next_signal+=1
    for t in range(max_h, n):
        # if signal time, update targets
        if t == next_signal:
            for base, h, sc, thr in [('A',hA,scA,thrA),('B',hB,scB,thrB),('C',hC,scC,thrC)]:
                cur=mids[base][t]
                past_idx=t-h
                if past_idx >=0:
                    past=mids[base][past_idx]
                else:
                    past=float('nan')
                if np.isfinite(cur) and np.isfinite(past):
                    ret=cur-past
                    if abs(ret) < thr:
                        tgt=0.0
                    else:
                        tgt=float(np.clip(ret/sc, -1, 1))
                    if tgt*prev_pos[base] >0:
                        tgt=0.7*tgt+0.3*prev_pos[base]
                        if tgt>1: tgt=1
                        if tgt<-1: tgt=-1
                    prev_pos[base]=tgt
                # update target lots
                target_lots[base]=prev_pos[base]*15
                # collect for IC if future exists
                if t+50 < n and np.isfinite(mids[base][t]) and np.isfinite(mids[base][t+50]):
                    targets_list[base].append(prev_pos[base])
                    fwd_list[base].append(mids[base][t+50]-mids[base][t])
            next_signal+=10
        # execution: move pos_lots toward target_lots by at most 2 lots
        for base in ['A','B','C']:
            delta = target_lots[base] - pos_lots[base]
            if delta > 2:
                delta = 2
            elif delta < -2:
                delta = -2
            else:
                # within 2
                pass
            if abs(delta) > 1e-9:
                # cost is half spread of primary at this step (if spread is nan, skip cost?)
                spr = spreads[base][t]
                if np.isfinite(spr):
                    cost += abs(delta) * spr * 0.5
                # also inventory change will affect pnl via position? trades happen at mid +/- spread/2 so cost already accounted; pnl from price move will be accounted separately
                pos_lots[base] += delta
        # pnl from price move from t to t+1 : pos_lots * (mid[t+1]-mid[t])
        if t+1 < n:
            for base in ['A','B','C']:
                if np.isfinite(mids[base][t]) and np.isfinite(mids[base][t+1]):
                    d = mids[base][t+1]-mids[base][t]
                    gross += pos_lots[base] * d
    net = gross - cost
    # compute IC
    ic_per={}
    for base in ['A','B','C']:
        a=np.array(targets_list[base])
        b=np.array(fwd_list[base])
        if len(a)>100 and np.std(a)>1e-9:
            ic_per[base]=float(np.corrcoef(a,b)[0,1])
        else:
            ic_per[base]=float('nan')
    all_t=np.concatenate([np.array(targets_list[b]) for b in ['A','B','C']])
    all_f=np.concatenate([np.array(fwd_list[b]) for b in ['A','B','C']])
    overall=float(np.corrcoef(all_t,all_f)[0,1]) if len(all_t)>100 and np.std(all_t)>1e-9 else float('nan')
    return gross,cost,net,ic_per,overall

