                if np.isfinite(pv) and np.isfinite(px):
                    past=(pv+px)*0.5
                elif np.isfinite(pv):
                    past=pv
                elif np.isfinite(px):
                    past=px
            if not (np.isfinite(cur) and np.isfinite(past)):
                out[base]=float(s.get(base,0.0))
