    target_lots={'A':0.0,'B':0.0,'C':0.0}
    gross=0.0; cost=0.0
    # align signals? each asset signals every 10 steps but based on its own past horizon. The strategy updates all every 10 steps using each base's h
    next_signal=max_h
    while next_signal%10!=0: next_signal+=1
    # but if horizons differ, earliest signal after max_h still uses each h
    for t in range(max_h, n):
        if t==next_signal:
            for base,h,sc,thr in [('A',hA,scA,thrA),('B',hB,scB,thrB),('C',hC,scC,thrC)]:
                cur=mids[base][t]
                past=mids[base][t-h] if t-h>=0 else float('nan')
                if np.isfinite(cur) and np.isfinite(past):
                    ret=cur-past
                    if abs(ret) < thr:
                        tgt=0.0
                    else:
                        tgt=float(np.clip(ret/sc,-1,1))
                    if tgt*prev_pos[base]>0:
                        tgt=(1-smooth)*tgt + smooth*prev_pos[base]
                        tgt=float(np.clip(tgt,-1,1))
                    prev_pos[base]=tgt
                target_lots[base]=prev_pos[base]*15
            next_signal+=10
        # execution
        for base in ['A','B','C']:
            delta=target_lots[base]-pos_lots[base]
            if delta>2: delta=2
            elif delta<-2: delta=-2
            if abs(delta)>1e-9:
                spr=spreads[base][t]
                if np.isfinite(spr):
                    cost+=abs(delta)*spr*0.5
                pos_lots[base]+=delta
        if t+1<n:
            for base in ['A','B','C']:
                if np.isfinite(mids[base][t]) and np.isfinite(mids[base][t+1]):
                    gross+=pos_lots[base]*(mids[base][t+1]-mids[base][t])
    net=gross-cost
    return net

