    mid=n//2
    def comp(s,e):
        past=[]; fut=[]
        for i in range(s, e - horizon - forward):
            if not (np.isfinite(b[i]) and np.isfinite(b[i+horizon]) and np.isfinite(b[i+horizon+forward])):
                continue
            past.append(b[i+horizon]-b[i])
            fut.append(b[i+horizon+forward]-b[i+horizon])
        if len(past)<100:
            return float('nan')
        p=np.array(past); f=np.array(fut)
        if np.std(p)==0 or np.std(f)==0:
